SHOP_TABLES = [
    {"name": "customers", "cols": [["id", "int pk"], ["name", "text"], ["city", "text, one NULL"], ["joined", "text YYYY-MM-DD"]]},
    {"name": "products", "cols": [["id", "int pk"], ["name", "text"], ["category", "text"], ["price", "int"]]},
    {"name": "orders", "cols": [["id", "int pk"], ["customer_id", "int → customers.id"], ["order_date", "text YYYY-MM-DD"], ["status", "delivered / shipped / pending / cancelled"]]},
    {"name": "order_items", "cols": [["order_id", "int → orders.id"], ["product_id", "int → products.id"], ["qty", "int"]]},
]


def T(id, db, tier, tag, title, task, want, ref, ordered=False, hint="", mins=None, verify=None):
    return {"id": id, "kind": "query", "db": db, "tier": tier, "tag": tag, "title": title, "task": task, "want": want,
            "ref": ref.strip(), "ordered": ordered, "hint": hint, "mins": mins or {1: 4, 2: 8, 3: 14}[tier], "verify": verify}


